import{_ as e,o,c as r,ah as n}from"./chunks/framework.Cma4l5FK.js";const i="/projects/xArm1s/en/latest/assets/image1.8noog8Ae.webp",a="/projects/xArm1s/en/latest/assets/image2.cMMNUvrM.webp",s="/projects/xArm1s/en/latest/assets/image2.DJgByAVW.webp",l="data:image/png;base64,",d="/projects/xArm1s/en/latest/assets/image4.YYtryJEf.webp",c="/projects/xArm1s/en/latest/assets/image5.CQEPKNn_.webp",h="/projects/xArm1s/en/latest/assets/image6.B2QSbLqm.webp",g="/projects/xArm1s/en/latest/assets/image7.DI_boAzz.webp",p="/projects/xArm1s/en/latest/assets/image8.DJmyI0ho.webp",m="/projects/xArm1s/en/latest/assets/image9.BeAt0MFu.webp",u="/projects/xArm1s/en/latest/assets/image10.CsBx_GMS.webp",w="/projects/xArm1s/en/latest/assets/image1.CQKwmd7j.webp",A="/projects/xArm1s/en/latest/assets/image2.BDAgtAGL.webp",P=JSON.parse('{"title":"2.Remote Control Learning","description":"","frontmatter":{},"headers":[],"relativePath":"docs/2. Remote Control Learning.md","filePath":"docs/2. Remote Control Learning.md"}'),y={name:"docs/2. Remote Control Learning.md"};function b(f,t,x,v,_,C){return o(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="_2-remote-control-learning" tabindex="-1">2.Remote Control Learning <a class="header-anchor" href="#_2-remote-control-learning" aria-label="Permalink to &quot;2.Remote Control Learning&quot;">​</a></h1><h2 id="_2-1-wireless-controller" tabindex="-1">2.1 Wireless Controller <a class="header-anchor" href="#_2-1-wireless-controller" aria-label="Permalink to &quot;2.1 Wireless Controller&quot;">​</a></h2><h3 id="_2-1-1-getting-ready" tabindex="-1">2.1.1 Getting Ready <a class="header-anchor" href="#_2-1-1-getting-ready" aria-label="Permalink to &quot;2.1.1 Getting Ready&quot;">​</a></h3><p>Step 1: Insert the wireless controller receiver into the controller board, as shown below:</p><img loading="lazy" height="767" width="1150" class="common_img" src="'+i+'" style="width:800px;"><p>Step 2: Prepare your own 2pcs AAA batteries and insert them into the battery slot. Please pay attention to the positive and negative poles.</p><img loading="lazy" height="482" width="1288" class="common_img" src="'+a+'" style="width:800px;"><h3 id="_2-1-2-device-connection" tabindex="-1">2.1.2 Device Connection <a class="header-anchor" href="#_2-1-2-device-connection" aria-label="Permalink to &quot;2.1.2 Device Connection&quot;">​</a></h3><p>Step 1: Turn on the xArm 1S robotic arm.</p><p>Step 2: Turn on the wireless controller. The red and green LEDs will flash.</p><p>Step 3: The robotic arm will automatically pair with the wireless controller after a few seconds. The red and green LED will be steady on after pairing. If there is only the red light or green light when you turn on, please press the “<strong>MODE</strong>” key.</p><p>Step 4: If the connection fails, please turn off the robotic arm and wireless controller, and then try again following the above steps.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><p><strong>Sleep Mode: If the robotic arm is not connected within 30 seconds after turning on the handle switch, or if no operation is performed on the handle within 5 minutes after connection, the handle will enter sleep mode. Pressing the &quot;<strong>Start</strong>&quot; key can restart the wireless controller.</strong></p></div><h3 id="_2-1-3-mode-instruction" tabindex="-1">2.1.3 Mode Instruction <a class="header-anchor" href="#_2-1-3-mode-instruction" aria-label="Permalink to &quot;2.1.3 Mode Instruction&quot;">​</a></h3><p>There are action group mode and single servo mode for the wireless controller. The default mode is action group mode.</p><p><strong>Action group mode</strong>: Press the key to run the corresponding actions.(For customers who buy the unassembled version, please download the action groups into the controller in advance.)</p><p><strong>Single servo mode</strong>: Press the key to rotate each servo.</p><p>Mode switching method: Press the “<strong>SELECT</strong>” first and then “<strong>START</strong>” until hearing a “<strong>Beep</strong>” sound. The mode will change from action group mode to single servo mode.</p><h3 id="_2-1-4-button-instruction" tabindex="-1">2.1.4 Button Instruction <a class="header-anchor" href="#_2-1-4-button-instruction" aria-label="Permalink to &quot;2.1.4 Button Instruction&quot;">​</a></h3><p>The method of pressing the combination key is to press and hold &quot;<strong>SELECT</strong>&quot; first, and then press the corresponding key.</p><table tabindex="0"><thead><tr><th style="text-align:center;">Button</th><th>Function</th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td>No.0 action group once（back to initial stance）</td></tr><tr><td style="text-align:center;">↑</td><td>No.1 action group once（rotation 1）</td></tr><tr><td style="text-align:center;">↓</td><td>No.2 action group once（grip to right 1）</td></tr><tr><td style="text-align:center;">←</td><td>No.3 action group once</td></tr><tr><td style="text-align:center;">→</td><td>No.4 action group once</td></tr><tr><td style="text-align:center;">△</td><td>No.5 action group once (rotation 2)</td></tr><tr><td style="text-align:center;">×</td><td>No.6 action group once (grip from left)</td></tr><tr><td style="text-align:center;">◻</td><td>No.7 action group once (grip from right 1)</td></tr><tr><td style="text-align:center;">○</td><td>No.8 action group once (grip to right 2)</td></tr><tr><td style="text-align:center;">L1</td><td>No.9 action group once (rotate to grip 1)</td></tr><tr><td style="text-align:center;">R1</td><td>No.10 action group once (grip to right 3)</td></tr><tr><td style="text-align:center;">L2</td><td>No.11 action group once (rotate to grip 2)</td></tr><tr><td style="text-align:center;">R2</td><td>No.12 action group once（turn and grip）</td></tr></tbody></table><p>Bottom under single servo mode</p><table><colgroup><col style="width:25%;"><col style="width:42%;"><col style="width:32%;"></colgroup><thead><tr><td>Button</td><td>Function</td><td>Servo</td></tr></thead><tbody><tr><td>START</td><td>All the servo back to the middle position</td><td>No. 1-6 servo</td></tr><tr><td>L2</td><td>Gripper open</td><td rowspan="2">No. 1servo</td></tr><tr><td>R2</td><td>Gripper close</td></tr><tr><td>L2</td><td>Turn left</td><td rowspan="2">No. 2 servo</td></tr><tr><td>L1</td><td>Turn right</td></tr><tr><td>◻</td><td>Forward</td><td rowspan="2">No. 3 servo</td></tr><tr><td>○</td><td>Backward</td></tr><tr><td>△</td><td>Forward</td><td rowspan="2">No. 4 servo</td></tr><tr><td>×</td><td>Backward</td></tr><tr><td>↑</td><td>Forward</td><td rowspan="2">No. 5 servo</td></tr><tr><td>↓</td><td>Backward</td></tr><tr><td>←</td><td>Turn left</td><td rowspan="2" style="text-align:left;">No. 6 servo</td></tr><tr><td>→</td><td>Turn right</td></tr></tbody></table> ## 2.2 App Control <h3 id="_2-2-1-app-installation" tabindex="-1">2.2.1 APP Installation <a class="header-anchor" href="#_2-2-1-app-installation" aria-label="Permalink to &quot;2.2.1 APP Installation&quot;">​</a></h3><p>Android user: Please transfer the installed pack to your smart phone to install.</p><p>iOS user: Please search “<strong>Wonderbot</strong>” in the App Store.</p><h3 id="_2-2-2-device-connection" tabindex="-1">2.2.2 Device Connection <a class="header-anchor" href="#_2-2-2-device-connection" aria-label="Permalink to &quot;2.2.2 Device Connection&quot;">​</a></h3><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p></p><ol><li><p><strong>Please turn on the Bluetooth and GPS service before opening the APP.</strong></p></li><li><p><strong>Please use the Bluetooth button in the APP to pair and connect with the device. Do not pair with the key in the phone settings.</strong></p></li><li><p><strong>This lesson takes the iOS version of the app as an example. The system version requirements: Android 7.0 or above, iOS 9.0 or above.</strong></p></li></ol></div><p>Step 1: Turn on the robotic arm.</p><p>Step 2: Open the Wonderbot APP to the interface as shown below.</p><img loading="lazy" height="561" width="997" class="common_img" src="'+s+'" style="width:800px;"><p>If your interface is different, please click <img loading="lazy" height="62" width="64" class="common_img" src="'+l+'" style="width:80px;"> icon and “<strong>Settings</strong>” to choose the “<strong>xArm</strong>”.</p><img loading="lazy" height="712" width="1265" class="common_img" src="'+d+'" style="width:800px;"><p>Step 3: Click the flashing Bluetooth icon on the interface to search for the device. Please select the “<strong>xArm</strong>” later.</p><img loading="lazy" height="539" width="955" class="common_img" src="'+c+'" style="width:800px;"><img loading="lazy" height="542" width="960" class="common_img" src="'+h+'" style="width:800px;"><p>Step 4: Wait for a while, the Bluetooth icon will stop flashing and stay on. The &quot;<strong>Bluetooth is connected</strong>&quot; prompt will appear.</p><img loading="lazy" height="712" width="1265" class="common_img" src="'+g+'" style="width:800px;"><h3 id="_2-2-3-mode-instruction" tabindex="-1">2.2.3 Mode Instruction <a class="header-anchor" href="#_2-2-3-mode-instruction" aria-label="Permalink to &quot;2.2.3 Mode Instruction&quot;">​</a></h3><p><strong>Mode 1 Model Remote Control： C</strong>ombine the two-dimensional screen with the button to control the movement of the robotic arm easily.</p><p><strong>Mode 2 Create Actions:</strong> Under this mode, you can program actions, debug, and record the data of the robotic arm.</p><p>Mode 3 My Action: You can store, display, and delete the custom actions.</p><p>For the detailed instruction of programming in the APP, please go to the folder “<strong>Expansion Lesson/Smart Phone APP Programming</strong>”.</p><h3 id="_2-2-4-button-instruction" tabindex="-1">2.2.4 Button Instruction <a class="header-anchor" href="#_2-2-4-button-instruction" aria-label="Permalink to &quot;2.2.4 Button Instruction&quot;">​</a></h3><ol><li>Under Mode 1 Model Remote Control, the interface is as follows:</li></ol><img loading="lazy" height="712" width="1265" class="common_img" src="'+p+'" style="width:800px;"><ol start="2"><li><p>On the right side, there is a 2D animation of xArm 1S. You can drag to control the movement, but also check the stance after rotation. Buttons on the left side support controlling the rotation of the gripper, wrist, and bottom.</p></li><li><p>Click “<strong>Action Group</strong>” to execute the action groups that are already downloaded into the robotic arm. For more details, please go to the folder “<strong>3. xArm 1S PC Software and APP Learning/Lesson 3 APP Custom Control</strong>”.</p></li><li><p>Click “<strong>Operation Instruction</strong>” for the operating method.</p></li></ol><img loading="lazy" height="712" width="1265" class="common_img" src="'+m+'" style="width:800px;"><ol start="5"><li>Click “<strong>Back to Start</strong>” to call all the servos back to the middle position.</li></ol><img loading="lazy" height="767" width="1150" class="common_img" src="'+u+'" style="width:800px;"><h2 id="_2-3-mouse-control" tabindex="-1">2.3 Mouse Control <a class="header-anchor" href="#_2-3-mouse-control" aria-label="Permalink to &quot;2.3 Mouse Control&quot;">​</a></h2><p>The control board of the xArm 1S robotic arm can analyze the mouse action information, and transfer the obtained data to the single-chip microcomputer through SPI for processing. Then the corresponding servos will execute the action.</p><h3 id="_2-3-1-getting-ready" tabindex="-1">2.3.1 Getting Ready <a class="header-anchor" href="#_2-3-1-getting-ready" aria-label="Permalink to &quot;2.3.1 Getting Ready&quot;">​</a></h3><p>Step 1: Please prepare your own mouse. If the wireless remote control receiver is in the controller board, don’t forget to take it out.</p><p>Step 2: Connect the mouse to the controller, as shown below:</p><img loading="lazy" height="750" width="1125" class="common_img" src="'+w+'" style="width:800px;"><h3 id="_2-3-2-device-connection" tabindex="-1">2.3.2 Device Connection <a class="header-anchor" href="#_2-3-2-device-connection" aria-label="Permalink to &quot;2.3.2 Device Connection&quot;">​</a></h3><p>Step 1: Turn on the robotic arm.</p><p>Step 2: Please wait for a second. The robotic arm will automatically pair with the mouse.</p><h3 id="_2-3-3-operation-instruction" tabindex="-1">2.3.3 Operation Instruction <a class="header-anchor" href="#_2-3-3-operation-instruction" aria-label="Permalink to &quot;2.3.3 Operation Instruction&quot;">​</a></h3><img loading="lazy" height="368" width="547" class="common_img" src="'+A+'" style="width:800px;"><table tabindex="0"><thead><tr><th style="text-align:center;">Operation</th><th style="text-align:center;">Servo</th></tr></thead><tbody><tr><td style="text-align:center;">Roll the scroll wheel</td><td style="text-align:center;">No.1 servo</td></tr><tr><td style="text-align:center;">Left mouse button + move left and right</td><td style="text-align:center;">No.2 servo</td></tr><tr><td style="text-align:center;">Right mouse button + move up and down</td><td style="text-align:center;">No.3 servo</td></tr><tr><td style="text-align:center;">Left mouse button + move up and down</td><td style="text-align:center;">No.4 servo</td></tr><tr><td style="text-align:center;">Mouse moves up and down</td><td style="text-align:center;">No.5 servo</td></tr><tr><td style="text-align:center;">Mouse moves right and left</td><td style="text-align:center;">No.6 servo</td></tr></tbody></table>',63)])])}const S=e(y,[["render",b]]);export{P as __pageData,S as default};
